import { Component, OnInit, ViewChild } from '@angular/core';
import { SafeUrl } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { IonContent, LoadingController, ToastController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { UserService } from '../../../../data/service/user/user.service';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { Urls } from '../../../../core/common/Urls';
import { GResponse } from '../../../../core/common/GResponse';
import { ITeacherUserDetailModel, ITeacherUserFilterModel, TeacherUserFilterModel } from '../../../../data/model/person/TeacherModel';
import { ICourseModel } from '../../../../data/model/course/CourseModel';

@Component({
  selector: 'app-teachers',
  templateUrl: './teachers.component.html',
  styleUrls: ['./teachers.component.scss']
})
export class TeachersComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;
  courses: ICourseModel[] = [];

  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  windowWidth = 1000;

  selectedTeacher: ITeacherUserDetailModel;
  teachers: ITeacherUserDetailModel[] = [];
  teacherFilter: ITeacherUserFilterModel = new TeacherUserFilterModel();
  isTeacherSelected = false;
  isLoadingList = true;
  isLoading = true;
  isFirstListShow = false;
  listShow = false;
  isCourseLoading = true;

  constructor(
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private teacherService: UserService
  ) {

    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();

      event.target.complete();
    }, 2000);
  }

  ionViewWillEnter() {

    this.teacherFilter = new TeacherUserFilterModel();

    this.activatedRoute.params.subscribe(params => {

      // tslint:disable-next-line: radix
      const id = parseInt(params.id);
      this.isTeacherSelected = false;
      this.isLoadingList = true;
      this.listShow = false;
      this.isLoading = true;

      if (Number.isNaN(id) || id <= 0) {

        this.teacherService.GetTeacherShowByFilter(this.teacherFilter).subscribe(

          res => {
            if (res.status === GResponse.SuccessStatus) {

              res.data.teachers.forEach(teacher => {

                if (this.teachers.find(e => e.id == teacher.id) == null) {

                  this.teachers.push(teacher);
                }
              });
              this.isLoadingList = false;
              this.isFirstListShow = true;
              this.listShow = true;
            } else if (res.status === GResponse.NotFoundStatus) {

              SharedIonic.toast(this.toastController, 'موردی یافت نشد');
            } else {

              SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
            }
          },
          err => {
            this.isLoadingList = false;
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      } else {
        this.isCourseLoading = true;

        this.teacherService.GetTeacherShowProfileDetailsById(id).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {

              this.selectedTeacher = res.data;
              this.isTeacherSelected = true;
              this.isLoading = false;

              this.teacherService.GetTeacherCoursesById(id).subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    this.courses = ress.data;
                    this.isCourseLoading = false;
                  } else {
                    this.courses = [];
                    this.isCourseLoading = false;
                  }
                },
                err => {
                  this.courses = [];
                  this.isCourseLoading = false;
                  SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
                }
              );
            } else {
              this.isTeacherSelected = false;
              this.router.navigateByUrl(Urls.Page404Url);
            }
          },
          err => {
            this.isTeacherSelected = false;
            SharedIonic.dismissLoading(this.loadingController);
            this.router.navigateByUrl(Urls.Page404Url);
          }
        );
      }
    });
  }

  loadData(event) {
    setTimeout(() => {

      if (this.teacherFilter.pageId >= this.teacherFilter.endPage) {

        event.target.disabled = true;
        return;
      }

      this.isLoadingList = true;
      this.teacherFilter.teachers = [];
      this.teacherFilter.pageId++;

      this.teacherService.GetTeacherShowByFilter(this.teacherFilter).subscribe(

        res => {
          if (res.status === GResponse.SuccessStatus) {

            res.data.teachers.forEach(teacher => {

              if (this.teachers.find(e => e.id == teacher.id) == null) {

                this.teachers.push(teacher);
              }
            });

            if (this.teacherFilter.pageId >= this.teacherFilter.endPage) {

              event.target.disabled = true;
            }
          } else if (res.status === GResponse.NotFoundStatus) {

            // SharedIonic.toast(this.toastController, 'موردی یافت نشد');
          } else {

            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
          this.isLoadingList = false;
        },
        err => {
          this.isLoadingList = false;
          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      );

      event.target.complete();
    }, 1500);
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onClick(id: number | string) {

    this.router
      .navigate(
        ['/Home', 'Search'],
        {
          queryParams:
          {
            categoryIds: [id],
            page: 1
          }
        });
  }

}
